#[test]
fn baseline_stale_reviewed_tree_must_not_delete_new_trunk_files() {
 let (dir,store)=new_repo();
 store.write_blob("s",Path::new("owned.txt"),b"owned\n","100644").unwrap();
 let (tree,_)=store.preview_ship("s").unwrap();
 std::fs::write(dir.path().join("unrelated.txt"),"other actor\n").unwrap();
 store.git(&["add","unrelated.txt"]).unwrap();
 store.git(&["commit","-m","another actor advanced trunk"]).unwrap();
 store.commit_ship("s",&tree,"stale reviewed tree").unwrap();
 assert!(store.git(&["show","HEAD:unrelated.txt"]).is_ok(),"stale ship deleted an unowned committed path after preview");
}
